fun interface OnResult { fun call(data: String) }

class Repository(private val scope: CoroutineScope) {
    fun loadAsync(id: String, onResult: OnResult): Job {          // SAM-convertible callback
        return scope.launch {
            onResult.call(fetch(id))                              // one completion, job.cancel() stops it
        }
    }

    suspend fun load(id: String): String = fetch(id)              // modern replacement
}
